/* -- CLIENTE (cadastro e alteracao) --------------------------------- */
	$("#formCliente").validate({
		rules: {
				'email': {
					required: true,
					email: true,
					remote: {
						url : "index.php?cmd=existeEmailCliente",
						data: {
							codigo: function() {
								return $("#codigoCliente").val();
							}
						}
					}
				},
				'senha': {
					minlength: 3,
					required: function(element)
					{
						return $("#codigoCliente").val() == "";
					}
				},
				'confSenha': {
					equalTo: "#senha",
					required: function(element)
					{
						return $("#senha").val() != "";
					}
				}
		},
		messages: {
			email: {
				remote: jQuery.format("<span class='unStyle'> Este email j&aacute; est&aacute; em uso! Por favor escolha outro!</span>")
			},

			senha: {
				minlength: "<span class='unStyle'> Sua senha deve ter no m&iacute;nimo 3 caracteres.</span>"
			},
			conf_senha: {
				minlength: "<span class='unStyle'> Este campo deve conter  no m&iacute;nimo 3 caracteres.</span>",
				equalTo: "<span class='unStyle'> Confirma&ccedil;&atilde;o de senha n&atilde;o corresponde com a senha digitada.</span>"
			}
		},
		invalidHandler: function(e, validator) {
			$("#validaErroContainerCliente").hide();
			var errors = validator.numberOfInvalids();
			if (errors) {
				var message = errors == 1
					? 'Você esqueceu de preencher o campo destacado'
					: 'Você esqueceu de preencher os ' + errors + ' campos que estão destacados';
				$(".errorCliente span").html(message);
				$(".errorCliente").show();
			} else {
				$(".errorCliente").hide();
			}
		},
		
		submitHandler: function() {
			$(".errorCliente").hide();
			$("#validaErroContainerCliente").hide();
			//$("#cmdCliente").val('validarClienteNovo');
			$("#botaoEnviar").hide();
			$("#tdBotaoAltInc").append(divLoading);
			
			
			var dados = $("#formCliente").serialize();
			
			$.post('index.php',dados, function(resultado) {
				$("#validaErroContainerCliente").hide();

				switch (resultado['status'])
				{
					case "alterado":
						var redireciona = "editou-cliente.html";
					break;
					case "incluido":
						var redireciona = "cadastrou-cliente.html";
					break;
					case "incluido-carrinho":
						var redireciona = "carrinho-endereco-entrega.html";
					break;
					case "novo":
						var redireciona = "cadastrar-cliente.html";
					break;
					case "erroOutro":
						var redireciona = "login.html";
					break;
					default:
						var redireciona = "cadastro.html";
					break;
				}
				//window.location = redireciona;
				$.redirecionarUrl(redireciona);
			}, "json");
			//$("#formCandidato").submit();
	
		}	 
	
	});
/* -- FIM CLIENTE (cadastro e alteracao) ---------------------------------*/

