	var listaOpcoes = $('#opcoesPagto');
	$('input.btSeleciona ').bind('click',function(){
		var parentLi = $(this).parents("li");
		if(!parentLi.hasClass('blOn')){
			parentLi.removeClass('blOff').addClass('blOn').siblings().removeClass('blOn').addClass('blOff');
			listaOpcoes.find('.optActive').removeClass('optActive').slideUp('fast');
			listaOpcoes.find('.blOn .ltOpts').slideDown('fast').addClass('optActive');
		} else {
			parentLi.removeClass('blOn').find('.optActive').slideUp('fast');
			$('#opcoesPagto li').removeClass('blOff');
		}
	});
	var optsContainer = $('#opcoesPagto').width();
	$('#opcoesPagto .jLtOpts').each(function(){
		var optsQuantidade = $('.bandeiras li', this).size();
		var optsMargin = parseInt($('.bandeiras li', this).css('margin-right'));

		$('.bandeiras li', this).width((optsContainer - (optsQuantidade - 1) * optsMargin) / optsQuantidade);
	});
	$('#opcoesPagto label.btDf1').eq(0).trigger("click");
